// frontend/static/js/render.js – Geräte-Karten
import { icons } from './icons.js';

let _actionHandler = null;

export function renderDevices(devices, actionHandler) {
    _actionHandler = actionHandler;
    const grid = document.getElementById('deviceGrid');
    if (!grid) return;

    grid.innerHTML = devices.map(d => renderCard(d)).join('');
    bindEvents(devices);
}

function renderCard(d) {
    const icon = icons[d.type] || icons.switch;
    const control = renderControl(d);

    return `
    <div class="device-card" data-id="${d.id}" data-type="${d.type}">
      <div class="device-card-header">
        <div>
          <div class="device-name">${icon} ${d.name}</div>
          <div class="device-type">${d.device} · ${d.type}</div>
        </div>
        ${d.type === 'switch' || d.type === 'dimmer' ? renderToggle(d) : ''}
      </div>
      ${control}
      <div class="device-status">${d.status || ''}</div>
    </div>`;
}

function renderToggle(d) {
    const checked = d.state === 'ON' ? 'checked' : '';
    return `
    <label class="toggle">
      <input type="checkbox" data-action="power" data-id="${d.id}" ${checked}>
      <span class="toggle-track"></span>
      <span class="toggle-thumb"></span>
    </label>`;
}

function renderControl(d) {
    if (d.type === 'dimmer') {
        const val = d.brightness ?? 50;
        return `
      <div class="slider-control">
        <input type="range" min="0" max="100" value="${val}" data-action="brightness" data-id="${d.id}">
        <div class="slider-label"><span>Helligkeit</span><span>${val}%</span></div>
      </div>`;
    }
    if (d.type === 'roller') {
        const val = d.position ?? 100;
        return `
      <div class="slider-control">
        <input type="range" min="0" max="100" value="${val}" data-action="position" data-id="${d.id}">
        <div class="slider-label"><span>Position</span><span>${val}%</span></div>
      </div>`;
    }
    if (d.type === 'thermostat') {
        const val = d.temperature ?? 20;
        return `
      <div class="slider-control">
        <input type="range" min="5" max="30" step="0.5" value="${val}" data-action="temperature" data-id="${d.id}">
        <div class="slider-label"><span>Soll-Temp</span><span>${val}°C</span></div>
      </div>`;
    }
    if (d.type === 'sensor') {
        const temp = d.temperature ?? '–';
        return `<div class="device-status" style="font-size:1.4rem;font-weight:700;color:var(--accent)">${temp}°C</div>`;
    }
    return '';
}

function bindEvents(devices) {
    // Toggles
    document.querySelectorAll('[data-action="power"]').forEach(el => {
        el.addEventListener('change', () => {
            _actionHandler(el.dataset.id, 'power', el.checked ? 'ON' : 'OFF');
        });
    });

    // Slider (debounced)
    document.querySelectorAll('input[type="range"]').forEach(el => {
        let timer;
        el.addEventListener('input', () => {
            const label = el.closest('.slider-control')?.querySelector('.slider-label span:last-child');
            const suffix = el.dataset.action === 'temperature' ? '°C' : '%';
            if (label) label.textContent = `${el.value}${suffix}`;
        });
        el.addEventListener('change', () => {
            clearTimeout(timer);
            timer = setTimeout(() => {
                _actionHandler(el.dataset.id, el.dataset.action, Number(el.value));
            }, 300);
        });
    });
}
